// Boss 时序调度器：与 tech-validation/src/bossTimeline.js 保持同一实现。
export const PHASE_THRESHOLDS: any = { 2: 0.7, 3: 0.35 };
export const TRANSITION_INVULNERABLE = 1.5;

export function groupEventsByPhase(events: any[], bossId: string): any {
  const grouped: any = { 1: [], 2: [], 3: [] };
  for (const event of events) {
    if (event.boss_id !== bossId) continue;
    if (!grouped[event.phase]) grouped[event.phase] = [];
    grouped[event.phase].push(event);
  }
  for (const phase of [1, 2, 3]) {
    grouped[phase].sort((a: any, b: any) => a.event_time - b.event_time);
  }
  return grouped;
}

export class BossTimeline {
  public bossId: string;
  public eventsByPhase: any;
  public skills: Map<string, any>;
  public onEvent: (event: any, entry: any) => void;
  public phase = 1;
  public elapsed = 0;
  public phaseTime = 0;
  public hpRatio = 1;
  public cursor = 0;
  public invulnerableUntil = 0;
  public cooldowns: any = {};
  public phaseReached: number[] = [1];
  public log: any[] = [];

  constructor({ bossId, events, skills = [], onEvent }: any) {
    this.bossId = bossId;
    this.eventsByPhase = groupEventsByPhase(events, bossId);
    this.skills = new Map(skills.map((skill: any) => [skill.skill_id, skill]));
    this.onEvent = onEvent ?? (() => {});
  }

  isInvulnerable(): boolean {
    return this.elapsed < this.invulnerableUntil;
  }

  setHpRatio(ratio: number): void {
    this.hpRatio = Math.max(0, Math.min(1, ratio));
    while (this.phase < 3 && this.hpRatio <= PHASE_THRESHOLDS[this.phase + 1]) {
      this.enterPhase(this.phase + 1);
    }
  }

  enterPhase(nextPhase: number): void {
    this.phase = nextPhase;
    this.phaseTime = 0;
    this.cursor = 0;
    this.cooldowns = {};
    this.invulnerableUntil = this.elapsed + TRANSITION_INVULNERABLE;
    this.phaseReached.push(nextPhase);
  }

  update(dt: number): void {
    this.elapsed += dt;
    this.phaseTime += dt;
    this.emitDueEvents();
  }

  emitDueEvents(): void {
    const list = this.eventsByPhase[this.phase] ?? [];
    while (this.cursor < list.length && list[this.cursor].event_time <= this.phaseTime + 1e-9) {
      const event = list[this.cursor];
      this.cursor += 1;
      this.fire(event);
    }
  }

  fire(event: any): void {
    const skill = event.skill_id ? this.skills.get(event.skill_id) : null;
    if (event.event_type === 'skill' && skill) {
      this.cooldowns[event.skill_id] = this.phaseTime + skill.cooldown;
    }
    if (event.event_type === 'transition' && event.warning > 0) {
      this.invulnerableUntil = Math.max(this.invulnerableUntil, this.elapsed + event.warning);
    }
    const entry = {
      time: Number(this.elapsed.toFixed(3)),
      phase: this.phase,
      eventType: event.event_type,
      skillId: event.skill_id,
      param: event.param,
      warning: event.warning,
      note: event.note,
    };
    this.log.push(entry);
    this.onEvent(event, entry);
  }
}
